  orbitTrapCenterY: f32,
  orbitTrapScale: f32,
  orbitTrapRotation: f32,
  orbitTrapAnisotropyX: f32,
  orbitTrapAnisotropyY: f32,
  orbitTrapPetals: f32,
  orbitTrapPetalDepth: f32,
  orbitTrapTwist: f32,
  orbitTrapPhase: f32,
  orbitTrapStartIteration: f32,
  orbitTrapEndIteration: f32,
  _orbitTrapPad0: f32,
  _orbitTrapPad1: f32,
  _orbitTrapPad2: f32,
